const $=s=>document.querySelector(s);let tab='profile',pending=null,currentUrl=null;const panel=$('#panel');function render(){panel.innerHTML=tab==='story'?'<p class="story">달빛이 닿는 오래된 서고에서,<br>흩어진 별들의 기억을 모으는 기록자.<br>아직 쓰이지 않은 다음 이야기는<br>당신의 손끝에서 시작됩니다.</p>':`<div class="section-label">${tab==='stats'?'전투 능력':'능력치'} <small>${tab==='stats'?'ATTRIBUTES':'STATUS'}</small></div>${[['공격력','2,840','82%'],['방어력','1,650','58%'],['생명력','12,480','91%']].map(([a,b,c])=>`<div class="stat"><span>${a}</span><strong>${b}</strong></div><div class="bar"><span style="--value:${c}"></span></div>`).join('')}`;panel.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:$('#app').classList.contains('no-motion')?0:400});}function selectTab(value){if(!['profile','stats','story'].includes(value))throw Error('Unknown tab');tab=value;document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});render();}document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));render();function replay(){for(const el of [$('#portrait'),$('#details')]){el.style.animation='none';void el.offsetWidth;el.style.animation=''}}$('#replay').onclick=replay;const dialog=$('#editor');function openEditor(){dialog.showModal()}$('#edit').onclick=openEditor;$('#customize').onclick=openEditor;$('#close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});function setFile(file){$('#error').textContent='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024){$('#error').textContent='10MB 이하의 PNG, JPG, WEBP 이미지를 선택해 주세요.';return}pending=file;$('#filename').textContent=file.name;}$('#file').onchange=e=>setFile(e.target.files[0]);$('#drop').ondragover=e=>{e.preventDefault()};$('#drop').ondrop=e=>{e.preventDefault();setFile(e.dataTransfer.files[0])};$('#form').onsubmit=async e=>{e.preventDefault();let url;if(pending){url=URL.createObjectURL(pending);try{const image=new Image();image.src=url;await image.decode()}catch{URL.revokeObjectURL(url);$('#error').textContent='이미지를 읽을 수 없어요. 다른 파일을 선택해 주세요.';return}if(currentUrl)URL.revokeObjectURL(currentUrl);currentUrl=url;$('#character').src=url;}$('#name').textContent=$('#inputName').value.trim()||'이름 없는 별';$('#roman').textContent=$('#inputRoman').value;$('#quote').textContent='“'+$('#inputQuote').value+'”';$('#character').alt=$('#name').textContent+' 캐릭터';dialog.close();replay();showToast('당신의 캐릭터가 무대에 등장했어요.');};let timer;function showToast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>showToast(b.dataset.skill));const themes={moon:['#0c1719','#132529','#d9bd7f'],wine:['#1b1019','#351c29','#debd86'],blue:['#101727','#1b2d43','#bdcfef']};function setTheme(theme){if(!themes[theme])throw Error('Unknown theme');['--bg','--surface','--accent'].forEach((key,i)=>document.documentElement.style.setProperty(key,themes[theme][i]));document.querySelectorAll('.swatch').forEach(b=>b.classList.toggle('selected',b.dataset.theme===theme));return {theme}}document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>setTheme(b.dataset.theme));$('#motion').onclick=()=>{const off=$('#app').classList.toggle('no-motion');$('#motion').textContent=off?'✧ 모션 꺼짐':'✦ 모션 켜짐';$('#motion').setAttribute('aria-pressed',String(!off))};if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_character_theme',description:'Change the visible character screen color theme.',inputSchema:{type:'object',properties:{theme:{type:'string',enum:['moon','wine','blue']}},required:['theme'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({theme})=>setTheme(theme)})).catch(()=>{})}catch{}}
